@pytest.mark.parametrize("path,obsolete_clause", CASES)
def test_direct_consumer_keeps_author_isolation_instead_of_model_exclusion(path, obsolete_clause):
    assert obsolete_clause not in " ".join((ROOT/path).read_text().split()), path + ": " + obsolete_clause
